package edu.minibank;
import edu.minibank.model.*;import edu.minibank.service.*;import edu.minibank.exception.InsufficientFundsException;import edu.minibank.util.Repository;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;
class BankServiceTest {
 @TempDir Path tempDir;
 @Test void depositIncreasesBalance() throws Exception {var r=new Repository<Account>();var s=new AccountStore();var b=new BankService(r,s,Path.of("target/test-data"));var a=b.openAccount("A","SAVINGS",500);b.deposit(a.getAccountNumber(),250);assertEquals(750,a.getBalance());}
 @Test void withdrawalBeyondAvailableLimitThrows(){var r=new Repository<Account>();var s=new AccountStore();var b=new BankService(r,s,Path.of("target/test-data"));var a=b.openAccount("A","SAVINGS",500);assertThrows(InsufficientFundsException.class,()->b.withdraw(a.getAccountNumber(),1));assertEquals(500,a.getBalance());}
 @Test void concurrentDepositsRemainAccurate(){var r=new Repository<Account>();var s=new AccountStore();var b=new BankService(r,s,Path.of("target/test-data"));var a=b.openAccount("A","CURRENT",0);int count=200;try(var p=new TransactionProcessor(s,b)){var jobs=new java.util.ArrayList<Transaction>();for(int i=0;i<count;i++)jobs.add(new Transaction(TransactionType.DEPOSIT,a.getAccountNumber(),null,10));var fs=p.process(jobs);for(var f:fs)assertDoesNotThrow(()->f.get(10,TimeUnit.SECONDS));}assertEquals(count*10L,a.getBalance());}
 @Test void statePersisterRoundTripsAccounts() throws Exception {Account original=new CurrentAccount("AC8888","Persisted",-100,500);Path file=tempDir.resolve("accounts.dat");StatePersister.save(new Account[]{original},file);Account restored=StatePersister.load(file)[0];assertEquals(original.getAccountNumber(),restored.getAccountNumber());assertEquals(-100,restored.getBalance());assertEquals(original,restored);}
 @Test void repositoryAlsoStoresCustomers(){var customers=new Repository<Customer>();var customer=new Customer("A","a@example.com","9876543210");customers.save(customer);assertSame(customer,customers.findById(customer.getCustomerId()));}
}
